const raw = $json.content?.parts?.filter(p=>!p.thought).map(p=>p.text||'').join('') ?? $json.text ?? '';
let narrative = '';
const s = raw.lastIndexOf('<<<REPORT>>>');
if (s!==-1) { narrative = raw.slice(s+12); const e = narrative.indexOf('<<<END>>>'); if(e!==-1) narrative=narrative.slice(0,e); narrative=narrative.trim(); }
if (narrative.length<50) narrative = raw.trim();
const d = $('Fetch Metrics (edit me)').item.json;
return { json: { ...d, narrative } };

